import { useEffect, useState } from 'react'
import { Cell, Pie, PieChart, PolarAngleAxis, PolarGrid, Radar, RadarChart, ResponsiveContainer } from 'recharts'
import { Button } from '../../components/Button'
import { Card } from '../../components/Card'
import { activeTrip, getCompletedTrip, notifyTripUpdated, submitReview, type CompletedTrip } from '../../services/tripService'

const feedback = ['food', 'culture', 'adventure', 'relaxation', 'Great value', 'Perfect pace', 'Would repeat']
const symbols = ['◐', '◧', '◌', '◒']
const colors = ['var(--tp-primary)', 'var(--tp-cta-strong)', 'var(--tp-success)', 'var(--tp-warning)']
export function CompletePage() {
  const [trip, setTrip] = useState<CompletedTrip | null>(null); const [ratings, setRatings] = useState<Record<string, number>>({}); const [feedbackChoice, setFeedbackChoice] = useState<Record<string, string[]>>({}); const [comments, setComments] = useState<Record<string, string>>({}); const [saving, setSaving] = useState<string | null>(null); const [error, setError] = useState(''); const [pointsEarned, setPointsEarned] = useState(0); const [linkCopied, setLinkCopied] = useState(false); const tripId = activeTrip.get()
  const load = () => { if (tripId) void getCompletedTrip(tripId).then((next) => { setTrip(next); setRatings(Object.fromEntries(next.reviews.map((review) => [review.vendorId, review.rating]))); setFeedbackChoice(Object.fromEntries(next.reviews.map((review) => [review.vendorId, review.tags]))); setComments(Object.fromEntries(next.reviews.map((review) => [review.vendorId, review.comment || '']))) }).catch((reason) => setError(reason instanceof Error ? reason.message : 'Unable to load trip completion.')) }
  useEffect(load, [tripId])
  const save = async (vendorId: string) => { if (!tripId || !ratings[vendorId]) return setError('Choose a star rating before submitting feedback.'); try { setSaving(vendorId); const result = await submitReview(tripId, { vendorId, rating: ratings[vendorId], tags: feedbackChoice[vendorId] || [], comment: comments[vendorId] }); setTrip((current) => current ? { ...current, preferences: result.preferences, loyaltyPoints: result.loyaltyPoints } : current); if (result.pointsEarned > 0) setPointsEarned(result.pointsEarned); notifyTripUpdated() } catch (reason) { setError(reason instanceof Error ? reason.message : 'Unable to save review.') } finally { setSaving(null) } }
  const referralLink = trip ? `${window.location.origin}/register?ref=${trip.referralCode}` : ''
  const copyReferralLink = async () => { if (!referralLink) return; try { await navigator.clipboard.writeText(referralLink); setLinkCopied(true); setTimeout(() => setLinkCopied(false), 2000) } catch { setError('Unable to copy the referral link.') } }
  const interestData = ['adventure', 'food', 'culture', 'nightlife', 'relaxation'].map((interest) => ({ interest: interest[0].toUpperCase() + interest.slice(1), score: Math.max(20, Math.min(100, 60 + ((trip?.preferences.weights?.[interest] || 0) * 8) + (trip?.preferences.interests?.includes(interest) ? 12 : 0))) }))
  return <section className="complete-page"><header className="complete-heading"><p className="eyebrow">Trip complete</p><h1 className="page-title">{trip?.trip.destination || 'Your trip'} left a mark.</h1><p className="page-copy">Your moments, spend, and feedback help make the next trip even more yours.</p></header>{error && <p className="auth-error">{error}</p>}<Card className="loyalty-card"><p className="eyebrow">Loyalty rewards</p><h2>{(trip?.loyaltyPoints ?? 0).toLocaleString()} points</h2>{pointsEarned > 0 && <p className="loyalty-earned">+{pointsEarned} points earned for completing this trip</p>}<p className="page-copy">Share your referral link - you'll earn points when a friend signs up with it.</p><div className="referral-link-row"><input aria-label="Your referral link" className="tp-input" readOnly value={referralLink} /><Button onClick={() => void copyReferralLink()} type="button" variant="secondary">{linkCopied ? 'Copied!' : 'Copy link'}</Button></div></Card><section className="recap-timeline">{(trip?.recap || []).map((moment, index) => <article className="recap-item" key={`${moment.time}-${moment.title}`}><div className="recap-photo" aria-label={`${moment.title} photo placeholder`}><span>{symbols[index % symbols.length]}</span><small>Trip memory</small></div><div><span>{moment.time}</span><h2>{moment.title}</h2><p>{moment.note}</p></div></article>)}</section><div className="complete-charts"><Card><h2>Spend summary</h2><div className="complete-pie"><ResponsiveContainer height="100%" width="100%"><PieChart><Pie cx="50%" cy="50%" data={trip?.spend || []} dataKey="value" innerRadius="55%" outerRadius="78%" paddingAngle={3}>{(trip?.spend || []).map((slice, index) => <Cell fill={colors[index % colors.length]} key={slice.name} />)}</Pie></PieChart></ResponsiveContainer></div><div className="spend-legend">{(trip?.spend || []).map((slice, index) => <span key={slice.name}><i style={{ background: colors[index % colors.length] }} />{slice.name} · ₹{slice.value.toLocaleString()}</span>)}</div></Card><Card className="preference-card"><p className="eyebrow">Trip DNA</p><h2>Preferences updated</h2><p>Review signals are stored in your profile and guide the next Composer itinerary.</p><div className="complete-radar"><ResponsiveContainer height="100%" width="100%"><RadarChart cx="50%" cy="50%" data={interestData} outerRadius="70%"><PolarGrid stroke="var(--tp-border)" /><PolarAngleAxis dataKey="interest" tick={{ fill: 'var(--tp-text-muted)', fontSize: 11 }} /><Radar dataKey="score" fill="var(--tp-primary)" fillOpacity={0.25} stroke="var(--tp-primary)" /></RadarChart></ResponsiveContainer></div></Card></div><section className="vendor-feedback"><p className="eyebrow">Share the signal</p><h2>Rate your trip partners</h2><div>{(trip?.vendors || []).map((vendor) => <Card className="vendor-rating" key={vendor.id}><strong>{vendor.name}</strong><div aria-label={`Rate ${vendor.name}`} className="star-rating">{[1, 2, 3, 4, 5].map((star) => <button aria-label={`${star} stars`} className={star <= (ratings[vendor.id] ?? 0) ? 'is-selected' : ''} key={star} onClick={() => setRatings((current) => ({ ...current, [vendor.id]: star }))} type="button">★</button>)}</div><div className="feedback-chips">{feedback.map((chip) => <button className={(feedbackChoice[vendor.id] || []).includes(chip) ? 'is-selected' : ''} key={chip} onClick={() => setFeedbackChoice((current) => ({ ...current, [vendor.id]: (current[vendor.id] || []).includes(chip) ? current[vendor.id].filter((item) => item !== chip) : [...(current[vendor.id] || []), chip] }))} type="button">{chip}</button>)}</div><textarea aria-label={`Feedback for ${vendor.name}`} className="tp-input" onChange={(event) => setComments((current) => ({ ...current, [vendor.id]: event.target.value }))} placeholder="Add a comment (optional)" value={comments[vendor.id] || ''} /><Button disabled={saving === vendor.id} onClick={() => void save(vendor.id)} type="button">{saving === vendor.id ? 'Saving…' : 'Save review'}</Button></Card>)}</div></section></section>
}
